from pathlib import Path
import base64
p=Path(__file__).resolve().parent
items=[('A','行内展开','沿服务逐层展开，最贴近现有设置页。'),('B','左右主从','左侧选服务，右侧持续阅读工具目录。'),('C','紧凑目录','以固定列对齐，便于集中检查多个服务。')]
css='''a{color:inherit;text-decoration:none}a:hover h2{text-decoration:underline}*{box-sizing:border-box}body{margin:0;background:#fcfcfb;color:#272725;font:14px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}header{padding:32px 32px 20px;display:flex;align-items:baseline;gap:20px}h1{font-size:20px;margin:0}p{margin:0;color:#6c6c69;font-size:12px}main{padding:0 32px 32px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.item{min-width:0}h2{font-size:14px;margin:0 0 4px}.caption{padding:12px 0 20px}.shot{border:1px solid #dededb;border-radius:8px;overflow:hidden;line-height:0}.shot img{width:100%;height:auto}.alt-title{grid-column:1/-1;margin-top:4px;border-top:1px solid #dededb;padding-top:20px;color:#6c6c69;font-size:12px}.mini{height:238px;border:1px solid #dededb;border-radius:8px;background:#f9f9f8;display:flex;padding:14px;gap:14px;overflow:hidden}.mini-nav{width:68px;border-right:1px solid #ddd;font-size:10px;color:#6c6c69;line-height:2.7;flex:none}.mini-body{flex:1;min-width:0;font-size:12px}.mini-head{font-size:14px;font-weight:600;margin-bottom:14px}.mini-row{padding:10px 0;border-bottom:1px solid #e1e1df;display:flex;justify-content:space-between;gap:10px}.mini-row span{color:#6c6c69;font-size:10px}.active{background:#e9e9e7;border-radius:5px;padding:4px}.mini-table{display:grid;grid-template-columns:100px 1fr;gap:0 12px}.mini-table div{padding:8px 0;border-bottom:1px solid #e1e1df;font-size:10px}.mini-sources{display:flex;gap:12px;margin-bottom:10px;font-size:10px}.mini-sources b{border-bottom:1px solid #272725;padding-bottom:6px}@media(max-width:800px){main{grid-template-columns:1fr}header{display:block;padding:20px}main{padding:0 20px 20px}.mini{height:238px}}'''
content=''
for i,(a,n,d) in enumerate(items,1):
 img=base64.b64encode((p/f'dir-{i}.png').read_bytes()).decode()
 content+=f'<article class="item"><a href="dir-{i}.html"><div class="shot"><img alt="{n}原型截图" src="data:image/png;base64,{img}"></div><div class="caption"><h2>{a} / {n}</h2><p>{d}</p></div></a></article>'
content+='<div class="alt-title">另外三个备选结构，尚未制作完整交互</div>'
nav='<div class="mini-nav">设置<br>模型<br>代理<br><b>工具</b><br>MCP 服务<br>插件</div>'
for letter,title,desc,body in [
 ('D','分区折叠','每次聚焦一类能力，首页最简。','<div class="mini-row"><b>MCP 服务</b><span>4 个服务　⌄</span></div><div class="mini-row"><b>Skills</b><span>2 个已启用　⌄</span></div><div class="mini-row"><b>内置工具</b><span>查看能力　⌄</span></div><div class="mini-row"><b>命令环境</b><span>查看详情　⌄</span></div>'),
 ('E','分类目录','用内容索引快速定位能力来源。','<div class="mini-sources"><b>MCP 服务</b><span>Skills</span><span>内置工具</span></div><div class="mini-row"><b>文件服务</b><span>3 个工具</span></div><div class="mini-row"><b>文档检索</b><span>2 个工具</span></div><div class="mini-row"><b>设计资源</b><span>连接异常</span></div>'),
 ('F','工具索引','先找工具，再追溯它所属的服务。','<div class="mini-table"><div><b>工具名称</b></div><div>来源</div><div>read_file</div><div>文件服务</div><div>list_directory</div><div>文件服务</div><div>search_documents</div><div>文档检索</div><div>get_document</div><div>文档检索</div></div>')]:
 content+=f'<article class="item"><div class="mini">{nav}<div class="mini-body"><div class="mini-head">工具</div>{body}</div></div><div class="caption"><h2>{letter} / {title}</h2><p>{desc}</p></div></article>'
html=f'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Magi 工具页设计方向</title><style>{css}</style><header><h1>Magi 工具设置</h1><p>三份可交互初稿，共用 Magi 主题。点击上方截图进入演示。</p></header><div style="padding:0 32px 20px"><a href="tools-directory.html" style="display:inline-block;padding:8px 14px;border-radius:8px;background:#272725;color:#fcfcfb;font-size:12px">已选 C：打开细化后的交互原型</a></div><main>{content}</main></html>'
(p/'index.html').write_text(html);(p/'thumbs.html').write_text(html)
